 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    color = min((v for v in counts if v != 0), key=lambda v: counts[v])
    points = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    # The original stamp is the largest connected component of the rare color.
    components = []
    while points:
        seed = points.pop()
        comp = {seed}
        q = [seed]
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in points:
                    points.remove(p); comp.add(p); q.append(p)
        components.append(comp)
    shape_cells = max(components, key=len)
    r0 = min(r for r, c in shape_cells)
    c0 = min(c for r, c in shape_cells)
    shape = [(r-r0, c-c0) for r, c in shape_cells]
    out = [row[:] for row in grid]
    for dr in range(h):
        for dc in range(w):
            cells = [(dr+sr, dc+sc) for sr, sc in shape]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
